function esc(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
function pageUrl(slug){return `page.html?slug=${encodeURIComponent(slug)}`;}
function servicePageUrl(slug){
  if(['emergency','drain-cleaning','sewer-camera','sewer-line','sump-pump','leak-pipe','gas-line','water-treatment','fixtures'].includes(slug))return pageUrl(slug);
  if(slug==='water-heater')return pageUrl('water-heater');
  if(slug==='commercial')return pageUrl('commercial');
  return `${pageUrl('services')}#service-${slug}`;
}

function submenu(id,label,href,items,extraClass=''){
  return `<div class="nav-item nav-item--has-submenu"><a href="${href}">${label}</a><button class="submenu-toggle" type="button" aria-expanded="false" aria-controls="${id}"><span class="screen-reader-text">Open ${label.toLowerCase()} menu</span><span aria-hidden="true">▾</span></button><div class="nav-submenu ${extraClass}" id="${id}">${items.map(([text,url])=>`<a href="${url}">${text}</a>`).join('')}</div></div>`;
}

function header(){
  const allServices=[['All Plumbing Services',pageUrl('services')],['Residential Plumbing',pageUrl('residential')],['Commercial Plumbing',pageUrl('commercial')],...serviceInventory.filter(([slug])=>slug!=='commercial').map(([slug,name])=>[name,servicePageUrl(slug)])];
  const residential=[['Residential Plumbing Overview',pageUrl('residential')],...serviceInventory.filter(([slug])=>slug!=='commercial').map(([slug,name])=>[name,servicePageUrl(slug)])];
  const commercialSlugs=new Set(['emergency','drain-cleaning','sewer-camera','sewer-line','water-heater','leak-pipe','gas-line','water-treatment']);
  const commercial=[['Commercial Plumbing Overview',pageUrl('commercial')],...serviceInventory.filter(([slug])=>commercialSlugs.has(slug)).map(([slug,name])=>[name,servicePageUrl(slug)])];
  return `<div class="topbar"><div class="wrap"><span>24/7 Emergency Plumbing Help</span><a class="topbar-phone" href="${business.phoneHref}">Call ${business.phoneDisplay}</a></div></div><header class="site-header"><div class="wrap nav"><a class="brand" href="${pageUrl('home')}" aria-label="${business.name} home"><img src="assets/images/official-primary-horizontal-transparent.png" alt="Frost and Kretsch Plumbing"></a><nav class="nav-links" id="primary-menu" aria-label="Primary"><a href="${pageUrl('home')}">Home</a><a href="${pageUrl('about')}">About</a>${submenu('services-submenu','Services',pageUrl('services'),allServices)}${submenu('residential-submenu','Residential',pageUrl('residential'),residential)}${submenu('commercial-submenu','Commercial',pageUrl('commercial'),commercial,'nav-submenu--commercial')}<a href="${pageUrl('contact')}">Contact Us</a></nav><button class="menu-btn" type="button" aria-controls="primary-menu" aria-expanded="false">Menu</button><a class="btn btn-primary btn-small nav-phone" href="${business.phoneHref}">Call now</a></div></header>`;
}

function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-main"><div class="footer-brand"><div class="footer-logo-panel"><img src="assets/images/official-primary-horizontal-transparent.png" alt="Frost and Kretsch Plumbing"></div><p>Residential, commercial, drain, sewer, and 24/7 emergency plumbing service across Macomb, Oakland, and Wayne counties.</p><p>${business.address}</p><a class="footer-phone" href="${business.phoneHref}">${business.phoneDisplay}</a></div><nav class="footer-col" aria-label="Footer services"><h3>Services</h3><a href="${pageUrl('services')}">All plumbing services</a><a href="${pageUrl('residential')}">Residential plumbing</a><a href="${pageUrl('commercial')}">Commercial plumbing</a><a href="${pageUrl('water-heater')}">Water heaters</a></nav><nav class="footer-col" aria-label="Footer company links"><h3>Company</h3><a href="${pageUrl('about')}">About</a><a href="${pageUrl('service-areas')}">Service Areas</a><a href="${pageUrl('contact')}">Contact</a><span>XML Sitemap</span></nav></div><div class="footer-legal"><span>© 2026 Frost &amp; Kretsch Plumbing</span><span class="footer-policy-links"><span>Privacy</span><span>Terms &amp; Conditions</span></span><span>Designed by Blue Nova Marketing</span><span class="version-badge">Static review mockup • not production</span></div></div></footer>`;}

function trustBar(){return `<section class="trust-bar"><div class="wrap trust-grid"><div class="trust-item"><b>Chesterfield based</b><span>One verified plumbing business</span></div><div class="trust-item"><b>Call anytime</b><span>24/7 emergency availability</span></div><div class="trust-item"><b>Homes + businesses</b><span>Residential and commercial plumbing</span></div><div class="trust-item"><b>Three-county coverage</b><span>Macomb, Oakland, and Wayne</span></div></div></section>`;}
function cta(title='Need plumbing help?'){return `<section class="cta"><div class="wrap"><div><h2>${esc(title)}</h2><p>Tell us what is happening, where the property is located, and whether the problem is active or urgent.</p></div><a class="btn btn-secondary" href="${business.phoneHref}">Call ${business.phoneDisplay}</a></div></section>`;}
