function locationServicePage(data){
  const serviceLinks=['emergency','drain-cleaning','sewer-camera','water-heater','sump-pump','leak-pipe'].map(slug=>{const item=serviceInventory.find(([key])=>key===slug);return `<a href="${servicePageUrl(slug)}">${esc(item[1])} →</a>`;}).join('');
  return `${header()}<main id="main"><section class="hero" style="--hero:url('${data.hero}');--hero-position:${data.position}"><div class="wrap"><div class="hero-content"><div class="eyebrow">${esc(data.eyebrow)}</div><h1>${esc(data.h1)}</h1><p>${esc(data.intro)}</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div></div></div></section><section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">${esc(data.city)} property context</div><h2>Local conditions shape the right plumbing response.</h2><p>${esc(data.local)}</p><p><strong>Service-area disclosure:</strong> Frost &amp; Kretsch Plumbing has no office in ${esc(data.city)}. Calls are dispatched from the verified headquarters at ${business.address}.</p><h2>Reasons customers call from ${esc(data.city)}</h2><ul>${data.calls.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></article><aside class="sidebar"><div class="sidebar-card"><h3>Focused service pages</h3>${serviceLinks}</div><div class="sidebar-card"><h3>Dispatch base</h3><p>${business.address}</p><a href="${business.phoneHref}">${business.phoneDisplay}</a></div></aside></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Not interchangeable copy</div><h2 class="section-title">What is specific to ${esc(data.city)}.</h2></div><p class="lead">These details help customers describe the property and help the service team choose the right diagnostic path.</p></div><div class="principle-grid">${data.issues.map(([title,copy])=>`<article class="principle-card"><h3>${esc(title)}</h3><p>${esc(copy)}</p></article>`).join('')}</div></div></section>${faq(data.faqs)}${reviewsSection()}${cta(`Request plumbing service for a ${data.city} property`)}</main>${footer()}`;
}

const seoServicePages={
  emergency:{hero:'images/emergency-van-wrap-v16.jpg',eyebrow:'Same-day and 24-hour plumbing',h1:'A same-day plumber for urgent problems—24 hours a day.',lead:'When water, sewage, or a failed plumbing system is actively threatening the property, call Frost & Kretsch Plumbing. The Chesterfield team triages urgent calls across Macomb, Oakland, and Wayne counties.',introTitle:'Searching for a plumber near me because the problem cannot wait?',paragraphs:['A “plumber near me” search is usually a request for two things: a qualified team that serves the address and a realistic response path. Call with the location, affected fixtures, when the problem began, and whether water or sewage is still moving.','Same-day plumber availability depends on the location, active workload, access, and nature of the emergency. The phone team will identify immediate safety steps and the most appropriate dispatch window rather than promise a time that cannot be met.'],issues:[['Call immediately','Active supply-line leaks, burst piping, sewage entering the building, no usable plumbing, a failed sump during rising water, or a leaking water heater.'],['Reduce damage safely','Use a known shutoff only when it can be reached without entering standing water or approaching electrical hazards. Do not use fixtures during a suspected sewer backup.'],['Prepare useful details','Share the address, property type, visible source, affected rooms or fixtures, water-shutoff status, and any recent freezing, excavation, or storm conditions.']],faqs:[['Does 24-hour service mean someone answers overnight?','Yes. Call the main number at any hour for urgent plumbing conditions. Dispatch timing depends on location, safety, access, and the calls already in progress.'],['Can I request a same-day plumber for a non-emergency?','Yes. Same-day availability may be possible for leaks, clogs, water-heater failures, and other time-sensitive problems. Call early and describe the full condition.'],['What should I do during a sewage backup?','Stop using water and fixtures, keep people and pets away from the affected area, and call for service. Avoid chemical drain cleaners because they add exposure risk for occupants and technicians.']]},
  'drain-cleaning':{hero:'images/zdpK0a1s.webp',eyebrow:'Drain cleaning and hydro jetting',h1:'Drain cleaning near you—with hydro jetting for buildup that keeps returning.',lead:'Frost & Kretsch Plumbing clears stoppages, identifies repeat-clog patterns, and recommends mechanical cleaning, hydro jetting, or camera inspection based on the actual line.',introTitle:'Compare drain cleaning companies by the diagnostic plan—not only the opening price.',paragraphs:['Customers searching for “drain cleaning near me” need more than a temporary hole through a blockage. The technician should identify which fixtures are involved, select a safe access point, restore flow, and explain whether grease, scale, roots, damage, or a larger sewer condition may be responsible.','A search for “drain jetting near me” or “hydrojet drain cleaning near me” often follows repeated snaking. Hydro jetting uses controlled high-pressure water to scour suitable pipe walls. It can be effective for grease, sludge, and certain buildup, but it is not automatically right for a damaged or fragile line.'],issues:[['Cable drain cleaning','A mechanical cable can open many localized stoppages and is often the first practical step for a newly clogged fixture or branch drain.'],['Hydro jetting / drain jetting','High-pressure water cleans the pipe circumference more thoroughly when pipe condition, access, and the type of buildup make jetting appropriate.'],['Camera-guided next step','A camera can document roots, offsets, breaks, standing water, or recurring buildup after flow is restored and the line can be viewed.']],faqs:[['Is hydro jetting better than snaking?','They solve different problems. Cabling can open a blockage quickly; hydro jetting can remove more wall buildup in a suitable line. Pipe condition, access, and the source of the clog determine the best method.'],['How do I choose among drain cleaning companies?','Ask whether the company will diagnose which line is affected, explain the cleaning method, protect the work area, and recommend a camera only when it can answer a useful question.'],['Can you clean kitchen, laundry, floor, and main drains?','Yes. Tell us which fixtures are slow or backed up and whether several fixtures changed at the same time. That pattern helps identify a branch drain versus the main sewer.']]},
  'sewer-camera':{hero:'images/camera-live.jpg',eyebrow:'Sewer line cleaning and camera inspection',h1:'Sewer line cleaning, camera inspection, and a clear repair path.',lead:'Recurring backups need evidence. Frost & Kretsch Plumbing restores flow, inspects accessible sewer piping, and separates cleaning needs from repair or excavation decisions.',introTitle:'A “sewer line cleaning near me” search should lead to more than repeated clearing.',paragraphs:['Sewer symptoms can come from roots, grease, scale, offsets, bellies, breaks, collapsed pipe, or a public-system condition. Cleaning may restore flow, while a camera inspection can show why the problem returned and where a defect is located.','Hydro jetting may remove roots and heavy buildup from a structurally suitable sewer line. Camera work before or after cleaning depends on whether the line can be traversed and whether the footage will change the recommendation.'],issues:[['Restore usable flow','The first priority during an active backup is to stop fixture use, establish safe access, and clear the blockage when conditions allow.'],['Inspect with purpose','Camera inspection documents the line’s interior, direction, defects, and problem areas; locating equipment can help map an underground point.'],['Repair only when justified','Spot repair, lining, excavation, or replacement should follow observable conditions, access constraints, and the remaining service life of the pipe.']],faqs:[['When should a sewer camera be used?','A camera is especially useful after recurring clogs, before a major repair, when buying a property with a concerning history, or when the technician needs to locate a defect.'],['Can a camera see through standing sewage or a complete blockage?','Not reliably. The line may need to be opened and cleaned before useful footage can be captured.'],['Is sewer line cleaning the same as hydro jetting?','Hydro jetting is one sewer-cleaning method. Mechanical cutting or cabling may be better for some blockages, while jetting may be better for wall buildup in structurally sound pipe.']]}
};

