function seoServicePage(data){return `${header()}<main id="main"><section class="hero" style="--hero:url('${data.hero}');--hero-position:center 48%"><div class="wrap"><div class="hero-content"><div class="eyebrow">${esc(data.eyebrow)}</div><h1>${esc(data.h1)}</h1><p>${esc(data.lead)}</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div></div></div></section>${trustBar()}<section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Choose the right next step</div><h2>${esc(data.introTitle)}</h2>${data.paragraphs.map(copy=>`<p>${esc(copy)}</p>`).join('')}<div class="callout"><strong>Service base:</strong> Every call is handled by Frost &amp; Kretsch Plumbing at ${business.address}. Service-area pages do not represent separate offices.</div></article><aside class="sidebar"><div class="sidebar-card"><h3>Related service paths</h3><a href="${servicePageUrl('emergency')}">24-Hour Emergency Plumbing →</a><a href="${servicePageUrl('drain-cleaning')}">Drain Cleaning &amp; Hydro Jetting →</a><a href="${servicePageUrl('sewer-camera')}">Sewer &amp; Camera Inspection →</a><a href="${servicePageUrl('sewer-line')}">Sewer Line Repair →</a></div><div class="sidebar-card"><h3>Call the main number</h3><a href="${business.phoneHref}">${business.phoneDisplay}</a><p>Macomb • Oakland • Wayne</p></div></aside></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Diagnosis before escalation</div><h2 class="section-title">The service path should match the evidence.</h2></div></div><div class="principle-grid">${data.issues.map(([title,copy])=>`<article class="principle-card"><h3>${esc(title)}</h3><p>${esc(copy)}</p></article>`).join('')}</div></div></section>${faq(data.faqs)}${reviewsSection()}${cta()}</main>${footer()}`;}

function serviceAreasPageV2(){const linked=Object.fromEntries(Object.entries(priorityCities).map(([county,cities])=>[county,cities.map(city=>{const slug=city.toLowerCase().replace(/\./g,'').replace(/\s+/g,'-');return `<a href="${pageUrl(slug)}">${esc(city)}</a>`;}).join(' • ')]));return serviceAreasPage().replace(/\$\{cities\.map[\s\S]*?join\(''\)\}/,'').replace('Communities served across three counties.','Nine focused community pages—one headquarters and eight true service areas.').replace('These local pages help customers confirm service coverage and connect directly to the plumbing service that fits the problem.','Each page reflects local housing, drainage, and infrastructure context. Only Chesterfield is an office; all other communities are served from that headquarters.').replace(/<div class="county-grid">[\s\S]*?<\/div><\/div><\/section><section class="section">/,`<div class="county-grid">${Object.entries(linked).map(([county,links])=>`<article class="county-card"><h3>${county}</h3><p>${links}</p></article>`).join('')}</div></div></section><section class="section">`);}

