const remainingServicePages={
  'sewer-line':{
    hero:'images/excavation-uniform-v3.png',eyebrow:'Sewer repair and replacement',h1:'Sewer line replacement and trenchless sewer repair—when the evidence supports it.',lead:'Camera findings, line location, pipe condition, access, and the failure pattern determine whether cleaning, spot repair, trenchless work, excavation, or full replacement is the responsible next step.',introTitle:'A recurring backup does not automatically mean the entire sewer must be replaced.',paragraphs:['Roots, separated joints, cracks, offsets, bellies, corrosion, and collapsed pipe can produce similar symptoms. The repair recommendation should follow useful camera footage, locating information, cleaning results, and the condition of the full accessible line.','Trenchless sewer repair can reduce surface disruption for some properties, but it is not a universal solution. Pipe material, diameter, alignment, collapse, access points, utilities, and local requirements all affect whether lining, bursting, spot repair, or open excavation is appropriate.','Frost & Kretsch Plumbing connects diagnosis to the repair plan so customers can understand what failed, where it failed, and why the proposed method fits the property.'],warningSigns:['Backups return soon after professional cleaning','A camera documents breaks, offsets, collapse, or extensive root entry','Sewer odor, soft ground, or unexplained wet areas appear along the line route','Several lower fixtures drain slowly or back up together'],steps:[['Document and locate','Restore enough flow for useful camera work, document the defect, and locate the affected underground section when conditions allow.'],['Compare repair methods','Evaluate spot repair, trenchless sewer repair, open excavation, or full sewer line replacement against pipe condition and site access.'],['Plan safe access','Account for utilities, landscaping, pavement, structures, permits, spoil, and restoration before opening the ground.']],related:['sewer-camera','drain-cleaning','emergency'],faqs:[['Is trenchless sewer repair always possible?','No. It depends on pipe material, condition, alignment, access, collapse, utilities, and the repair method available for that specific line.'],['How do I know whether I need repair or replacement?','The decision should be based on camera evidence, defect location, pipe condition, recurring history, remaining service life, and whether a localized repair will provide a durable result.'],['Do you excavate sewer lines?','Yes. Frost & Kretsch Plumbing can connect sewer diagnosis with planned excavation and underground repair when open access is the appropriate method.']]},
  'sump-pump':{
    hero:'images/sump-uniform-v3.png',eyebrow:'Sump pumps and backup protection',h1:'Sump pump repair near me, sump pump replacement, and battery-backup planning.',lead:'A sump system is only useful when the pump, float, check valve, power source, basin, discharge route, and backup plan work together before water rises.',introTitle:'Test the whole sump system—not only whether the motor makes noise.',paragraphs:['A pump can run and still fail to move enough water. A stuck float, blocked intake, failed check valve, undersized pump, restricted discharge, frozen exterior outlet, or power loss can leave the basin rising during the worst possible weather.','For sump pump repair, the technician evaluates the symptom and connected components. For sump pump replacement, capacity, head height, discharge routing, basin space, controls, and expected inflow matter more than simply matching the old label.','Battery-backup and water-powered backup options have different installation, maintenance, capacity, and utility requirements. The right backup is selected around the property and the failure scenario it needs to cover.'],warningSigns:['The pump hums, cycles rapidly, runs continuously, or does not start','Water rises close to the basement floor before the pump activates','The discharge line rattles, leaks, freezes, or sends water back toward the foundation','The home has no backup plan for power loss or primary-pump failure'],steps:[['Diagnose the system','Check pump operation, float movement, basin condition, check valve, electrical supply, discharge routing, and visible backup components.'],['Repair or replace','Correct a serviceable component or install a properly selected primary pump when condition or capacity justifies replacement.'],['Add backup protection','Review battery-backup, alarm, or water-powered options and explain ongoing testing and maintenance needs.']],related:['emergency','leak-pipe','sewer-camera'],faqs:[['When should a sump pump be replaced?','Replacement may be appropriate when the pump fails testing, cannot keep up with normal inflow, has unreliable controls, shows significant wear, or no longer fits the system requirements.'],['Will a battery backup run the pump during an outage?','A dedicated battery-backup system can operate its own backup pump during a power interruption, but runtime and capacity depend on the equipment, battery condition, water inflow, and maintenance.'],['How often should I test my sump pump?','Test it before wet seasons and after service, outages, or long idle periods. Follow the equipment instructions and keep the basin and discharge path safely accessible.']]},
  'leak-pipe':{
    hero:'images/leak-detection-v5.png',eyebrow:'Water leak detection and pipe repair',h1:'Water leak detection for hidden pipe leaks, slab leaks, and damaged supply lines.',lead:'The goal is to narrow the source before opening finished surfaces, then match the pipe repair to the confirmed material, location, pressure, and failure.',introTitle:'Visible water is not always directly below the failed pipe.',paragraphs:['Water can travel along framing, concrete, insulation, cabinets, or utility penetrations before it becomes visible. A useful leak investigation begins with fixture use, meter behavior, pressure, affected zones, timing, and the construction around the suspected line.','Water leak detection may include isolation, pressure testing, acoustic or thermal clues, moisture mapping, and inspection of accessible piping. No method can guarantee a hidden line will be located without access, but systematic testing reduces unnecessary opening.','A slab leak requires special planning because the failed line may be below concrete or may be rerouted rather than repaired in place. Pipe material, failure history, access, and the condition of the broader system guide the repair path.'],warningSigns:['The water meter moves when all known fixtures are off','A wall, ceiling, cabinet, or floor stays damp without an obvious source','Water pressure drops or a supply line makes an unexplained sound','A warm floor area, slab-edge moisture, or recurring concrete-floor dampness appears'],steps:[['Narrow the source','Review usage, isolate fixtures and branches, inspect accessible piping, and use appropriate detection tools.'],['Choose access and repair','Plan a focused opening, localized pipe repair, reroute, or broader replacement based on material and condition.'],['Verify the result','Restore service carefully, check repaired connections, and explain any drying, restoration, or monitoring that remains.']],related:['emergency','fixtures','water-heater'],faqs:[['Can every leak be found without opening a wall or floor?','No. Detection tools can narrow the source, but some failures require limited access to confirm the exact pipe and complete a durable repair.'],['What are signs of a slab leak?','Possible signs include unexplained meter movement, warm or damp floor areas, reduced pressure, sound of running water, or moisture near the slab edge. These symptoms can have other causes and require diagnosis.'],['Do you repair the pipe after locating the leak?','Yes. Repair options depend on pipe material, location, access, system condition, and whether a localized repair or reroute is more appropriate.']]},
  'gas-line':{
    hero:'images/tech-navy-f350-v16.jpg',eyebrow:'Gas piping service',h1:'Gas line installation and gas line repair planned around safety, load, and code.',lead:'New appliances, damaged piping, pressure problems, and suspected leaks require qualified evaluation—not a do-it-yourself test or temporary patch.',introTitle:'If you smell gas, treat it as an emergency before scheduling routine plumbing work.',paragraphs:['Leave the affected area, avoid switches, flames, engines, and phones near the suspected leak, and contact the gas utility or emergency services from a safe location. Do not re-enter until the appropriate authority says it is safe.','For planned gas line installation, the technician considers appliance demand, total connected load, pipe sizing, material, routing, shutoffs, venting coordination, access, testing, permits, and inspection requirements.','Gas line repair begins with making the condition safe and confirming the failed section. Corrosion, damaged fittings, appliance connectors, improper alterations, and pressure-test failures require different repair scopes.'],warningSigns:['A sulfur or rotten-egg odor is present near gas equipment or piping','A gas appliance is being added, moved, or replaced with different demand','Visible piping is corroded, damaged, unsupported, or has been struck','A utility, inspector, or contractor identifies a pressure-test or connection problem'],steps:[['Make safety the first step','Emergency odor or suspected release goes to the gas utility or emergency services before routine service proceeds.'],['Size and route correctly','Calculate demand and plan pipe sizing, material, shutoffs, access, testing, and inspection around the equipment.'],['Test the completed work','Perform required pressure or leak testing and coordinate permits or inspection when the job requires them.']],related:['emergency','water-heater','fixtures'],faqs:[['What should I do if I smell gas?','Leave the area immediately, avoid flames and electrical switches, and call the gas utility or emergency services from a safe location. Do not attempt to locate the leak yourself.'],['Can you install a gas line for a new appliance?','Yes, when the existing system has capacity and the route, pipe sizing, shutoffs, appliance requirements, permits, and inspection can be addressed correctly.'],['Does a gas line repair require a permit?','Requirements depend on the location and scope. Frost & Kretsch Plumbing will identify permit and inspection needs for the planned work.']]},
  'water-treatment':{
    hero:'images/softener-service.jpg',eyebrow:'Water softening and filtration',h1:'Water softener installation and whole-home water filtration matched to the water concern.',lead:'Hardness, sediment, chlorine taste, odor, iron, and other concerns do not all use the same treatment. Start with the water source, available test information, household demand, and maintenance expectations.',introTitle:'Choose treatment for a verified condition—not a generic equipment package.',paragraphs:['A water softener primarily addresses hardness minerals that cause scale and soap-performance problems. It does not remove every contaminant and should not be presented as a complete drinking-water solution by itself.','Whole-home water filtration can target sediment, taste, odor, chlorine, or other identified concerns depending on the media and system design. Private-well properties may require appropriate laboratory testing before treatment is selected.','Installation planning includes flow rate, pressure, drain access, bypass valves, electrical needs, equipment footprint, regeneration or cartridge maintenance, and how treated water will be routed through the home.'],warningSigns:['White scale returns quickly on fixtures, glass, or water-heating equipment','Soap performs poorly or laundry feels affected by hard water','Sediment, taste, odor, or discoloration persists at several fixtures','Existing treatment equipment leaks, stops regenerating, or no longer delivers expected results'],steps:[['Define the water concern','Confirm the source, symptoms, household demand, and available municipal or laboratory water information.'],['Select the treatment path','Compare softening, sediment filtration, carbon filtration, or a combined approach based on the verified goal.'],['Install for serviceability','Plan bypasses, drainage, power, clearance, and future salt, media, or cartridge maintenance.']],related:['water-heater','fixtures','leak-pipe'],faqs:[['What does a water softener remove?','A conventional softener exchanges hardness minerals such as calcium and magnesium. It is not designed to remove every contaminant or replace all filtration.'],['Do I need a water test before whole-home filtration?','Testing is strongly recommended when the concern is not already documented, especially for private wells, health-related questions, iron, odor, or unusual discoloration.'],['Can a softener and filter be installed together?','Yes, when both are justified. Equipment order, flow, pressure, drainage, maintenance, and the specific media must be planned as one system.']]},
  fixtures:{
    hero:'images/residential-uniform-v3.png',eyebrow:'Kitchen and bathroom fixture plumbing',h1:'Toilet repair, toilet installation, faucet repair, and fixture plumbing.',lead:'Repair the component that failed—or replace the fixture when condition, performance, access, or the planned update makes replacement the better value.',introTitle:'A leaking or unreliable fixture can waste water and damage the surfaces around it.',paragraphs:['Toilet problems can involve the fill valve, flapper, flush mechanism, supply connection, shutoff, wax seal, flange, drain, or the fixture itself. Movement at the base, recurring clogs, or moisture around the floor deserves diagnosis before a new toilet is installed.','Faucet repair may involve cartridges, stems, seals, aerators, supply lines, shutoffs, or mounting hardware. Corrosion, unavailable parts, finish condition, or repeated failure may make replacement more practical than another repair.','Kitchen and bathroom fixture installation should account for drain alignment, water pressure, shutoff condition, mounting, countertop or wall openings, manufacturer requirements, and protection of nearby finishes.'],warningSigns:['A toilet runs, rocks, leaks at the base, refills slowly, or clogs repeatedly','A faucet drips, becomes difficult to operate, loses flow, or leaks below the cabinet','A shutoff valve will not close or a supply connector shows corrosion or moisture','A new sink, vanity, toilet, disposal, or fixture does not align with existing plumbing'],steps:[['Diagnose the fixture and connections','Check the visible component, shutoffs, supplies, mounting, drainage, and surrounding surfaces before choosing repair or replacement.'],['Repair or install cleanly','Use compatible parts, protect finishes, set and connect the fixture, and address accessible failed connections.'],['Test operation','Verify filling, flushing, drainage, temperature, flow, shutoffs, and visible connections before the work is complete.']],related:['leak-pipe','drain-cleaning','water-treatment'],faqs:[['Should I repair or replace a leaking toilet?','The answer depends on the leak source, bowl and tank condition, flange, available parts, water use, appearance, and whether the fixture has recurring problems.'],['Can you install a customer-supplied faucet or toilet?','Often, yes. Confirm the model, included parts, compatibility, condition, and any warranty limitations when scheduling.'],['Why does my faucet have low flow after a repair or outage?','Debris can collect in an aerator or cartridge, but shutoffs, supply lines, pressure, and broader piping conditions may also be involved.']]}
};

function coreServicePage(data){const related=data.related.map(slug=>{const item=serviceInventory.find(([key])=>key===slug);return `<a href="${servicePageUrl(slug)}">${esc(item[1])} →</a>`;}).join('');return `${header()}<main id="main"><section class="hero" style="--hero:url('${data.hero}');--hero-position:center 48%"><div class="wrap"><div class="hero-content"><div class="eyebrow">${esc(data.eyebrow)}</div><h1>${esc(data.h1)}</h1><p>${esc(data.lead)}</p><div class="hero-actions"><a class="btn btn-primary phone-cta" href="${business.phoneHref}">Call ${business.phoneDisplay}</a><a class="btn btn-secondary" href="${pageUrl('contact')}">Request service</a></div></div></div></section>${trustBar()}<section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Diagnosis before work</div><h2>${esc(data.introTitle)}</h2>${data.paragraphs.map(copy=>`<p>${esc(copy)}</p>`).join('')}<h2>Warning signs to take seriously</h2><ul>${data.warningSigns.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><div class="callout"><strong>Service base:</strong> This service is handled by Frost &amp; Kretsch Plumbing at ${business.address}; service-area pages are not separate offices. Call ${business.phoneDisplay} or email ${business.email}.</div></article><aside class="sidebar"><div class="sidebar-card"><h3>Related plumbing services</h3>${related}</div><div class="sidebar-card"><h3>Chesterfield service base</h3><p>Frost &amp; Kretsch Plumbing<br>${business.address}</p><a href="${business.phoneHref}">${business.phoneDisplay}</a><a href="mailto:${business.email}">${business.email}</a></div></aside></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><div class="eyebrow">What the service involves</div><h2 class="section-title">A clear path from evidence to completed work.</h2></div></div><div class="principle-grid">${data.steps.map(([title,copy])=>`<article class="principle-card"><h3>${esc(title)}</h3><p>${esc(copy)}</p></article>`).join('')}</div></div></section>${faq(data.faqs)}${reviewsSection()}${cta()}</main>${footer()}`;}

function reviewsPage(){return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">Chesterfield headquarters reviews</div><h1>Customer feedback tied to the verified Frost &amp; Kretsch Plumbing profile.</h1><p>This page uses the Chesterfield headquarters Google profile—the source with 271 reviews—not the Warren profile.</p></div></section>${reviewsSection()}<section class="section"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Review-source clarity</div><h2>One company profile for the consolidated website.</h2><p>The consolidated fkplumbing.com website represents one plumbing business based in Chesterfield. Its review feed should therefore use the same verified headquarters entity that appears in the footer and LocalBusiness/Plumber schema.</p><p>Individual review cards will be loaded through the approved staging widget. The review count, rating, dates, and customer wording must come from that live source rather than being copied into page content.</p><h2>What to look for in customer feedback</h2><ul><li>Communication before and during the appointment</li><li>Clarity about the diagnosed condition and proposed work</li><li>Care around homes, businesses, and finished spaces</li><li>Follow-through on drain, sewer, equipment, and repair work</li></ul></article><aside class="sidebar"><div class="sidebar-card"><h3>Verified business</h3><p>Frost &amp; Kretsch Plumbing<br>${business.address}</p><a href="${business.phoneHref}">${business.phoneDisplay}</a><a href="mailto:${business.email}">${business.email}</a></div></aside></div></section>${cta('Need plumbing help from the Chesterfield team?')}</main>${footer()}`;}

function financingCouponsPage(){const offers=[['Drain cleaning','$20 off','Eligible drain-cleaning appointments'],['Hot-water replacement','$50 off','Qualifying water-heater replacement'],['General plumbing','$45 off','Qualifying general plumbing service'],['Sewer jetting','$99 off','Eligible sewer-jetting service']];return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">Current savings and payment planning</div><h1>Plumbing coupons—and a clear conversation about payment options.</h1><p>Mention the offer when scheduling and confirm that it applies to the planned work before service begins.</p></div></section><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Current offers</div><h2 class="section-title">Savings tied to real plumbing services.</h2></div><p class="lead">Offers may change and cannot be combined unless Frost &amp; Kretsch Plumbing confirms otherwise.</p></div><div class="cards">${offers.map(([name,amount,copy])=>`<article class="card"><div class="card-body"><div class="service-icon">${esc(amount)}</div><h3>${esc(name)}</h3><p>${esc(copy)}. Mention this offer when booking and confirm eligibility before work begins.</p></div></article>`).join('')}</div></div></section><section class="section section-alt"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Financing and payment questions</div><h2>Ask what options are currently available for larger repairs.</h2><p>No specific lender or financing program is represented in this review build because provider terms, eligibility, rates, and availability must be verified before publication. Call the office to ask whether a current payment or financing option applies to the proposed work.</p><h2>Coupon terms</h2><ul><li>Coupons cannot be combined with other offers unless confirmed.</li><li>Mention the coupon when scheduling service.</li><li>Offers apply only to qualifying work and may have exclusions.</li><li>Confirm the current offer before authorizing service.</li></ul></article><aside class="sidebar"><div class="sidebar-card"><h3>Confirm an offer</h3><a href="${business.phoneHref}">${business.phoneDisplay}</a><a href="mailto:${business.email}">${business.email}</a></div></aside></div></section>${cta('Ask about the current plumbing offer')}</main>${footer()}`;}

const consolidatedFaqs=[
  ['Emergency and scheduling',[['Do you provide 24-hour emergency plumbing service?','Yes. Call (586) 675-0097 at any hour for active leaks, sewage backups, burst piping, failed sump systems, and other urgent plumbing conditions.'],['Can I request a same-day plumber for a non-emergency?','Yes. Same-day availability depends on location, access, active workload, and the type of service needed.'],['What information should I have when calling?','Share the service address, property type, affected fixtures or systems, when the problem began, and whether water or sewage is actively spreading.']]],
  ['Drains and sewers',[['Is hydro jetting better than snaking?','They solve different problems. Cabling can open a blockage; hydro jetting can remove more wall buildup when pipe condition and access make it appropriate.'],['When should a sewer camera be used?','A camera is useful after recurring clogs, before major repair, or when the technician needs to document and locate a defect.'],['Is trenchless sewer repair always possible?','No. Pipe condition, alignment, access, collapse, utilities, material, and the selected method all affect eligibility.']]],
  ['Equipment and piping',[['Do you repair tank and tankless water heaters?','Yes. The service path includes diagnosis, repair, replacement, and installation planning for tank and tankless systems.'],['When should a sump pump be replaced?','Replacement may be appropriate when the pump fails testing, cannot keep up, has unreliable controls, or no longer fits the system requirements.'],['Can every hidden leak be found without opening a surface?','No. Detection tools can narrow the source, but some failures require limited access to confirm the exact pipe and complete a durable repair.'],['What should I do if I smell gas?','Leave the area, avoid flames and electrical switches, and call the gas utility or emergency services from a safe location.']]],
  ['Company and coverage',[['Where is Frost & Kretsch Plumbing located?','Frost & Kretsch Plumbing is located at 47212 Jefferson Ave, Chesterfield, MI 48047.'],['What areas do you serve?','The Chesterfield team serves properties across Macomb, Oakland, and Wayne counties. Call with the exact address to confirm coverage.'],['Are the city pages separate offices?','No. Only the Chesterfield headquarters address is published. Non-HQ city pages describe service coverage dispatched from Chesterfield.']]]
];
function faqPage(){return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">Plumbing questions answered</div><h1>Frequently asked questions about service, systems, and scheduling.</h1><p>Start here for common questions, then use the focused service page for deeper guidance about the plumbing condition.</p></div></section>${consolidatedFaqs.map(([title,items])=>`<section class="section section-alt"><div class="wrap faq-wrap"><div><div class="eyebrow">${esc(title)}</div><h2 class="section-title">Clear answers before you call.</h2></div><div class="faq-list">${items.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div></div></section>`).join('')}${cta()}</main>${footer()}`;}

function privacyPage(){return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">Last updated November 24, 2026</div><h1>Privacy Policy</h1><p>How information submitted through fkplumbing.com may be collected, used, protected, and shared.</p></div></section><section class="section"><div class="wrap article-copy"><div class="template-note"><strong>Review note:</strong> This refreshed policy corrects the business identity and replaces obsolete Warren-address language. It should receive legal review before production publication.</div><h2>Information we may collect</h2><p>Frost &amp; Kretsch Plumbing may collect information you choose to provide through forms, phone calls, email, text-message consent fields, or service requests. This may include your name, phone number, email address, service address, message, and details needed to respond to a plumbing request.</p><p>The website may also collect technical information through cookies, analytics, security tools, server logs, or similar technologies, including device, browser, referral, page-use, and approximate location information. Actual tools and cookie controls must be documented during staging integration.</p><h2>How information may be used</h2><ul><li>Respond to questions and schedule or provide requested plumbing service</li><li>Communicate about appointments, estimates, work, and service follow-up</li><li>Operate, secure, maintain, and improve the website</li><li>Measure website performance and marketing effectiveness</li><li>Meet legal, regulatory, insurance, accounting, and safety obligations</li></ul><h2>Text messages and email</h2><p>If you provide consent to receive service-related text messages, message and data rates may apply. Consent is not a condition of purchase. Message frequency varies. Reply STOP to opt out of text messages and HELP for help. Email communications may be used to respond to inquiries and provide service information.</p><h2>Sharing and service providers</h2><p>Information may be shared with trusted providers that help operate the website, communications, scheduling, analytics, security, payment, or service delivery. Information may also be disclosed when required by law, to protect rights or safety, or as part of a legitimate business transaction. Frost &amp; Kretsch Plumbing does not sell personal information for money.</p><h2>Data security and retention</h2><p>Reasonable administrative, technical, and physical safeguards are used to protect information. No internet transmission or storage method is completely secure. Information is retained only as long as reasonably necessary for the purpose collected, legal obligations, dispute resolution, and business records.</p><h2>Children’s privacy</h2><p>This website and its plumbing services are not directed to children under 13, and the business does not knowingly collect personal information from children under 13 through the website.</p><h2>Choices and contact</h2><p>You may request access, correction, or deletion of information where applicable, or ask a privacy question, by contacting:</p><p>Frost &amp; Kretsch Plumbing<br>${business.address}<br>${business.phoneDisplay}<br>${business.email}</p><p>Changes to this policy will be posted on this page with an updated effective date.</p></div></section></main>${footer()}`;}

function termsPage(){return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">Last updated November 24, 2026</div><h1>Website Terms &amp; Conditions</h1><p>Terms governing use of fkplumbing.com and its informational content.</p></div></section><section class="section"><div class="wrap article-copy"><div class="template-note"><strong>Review note:</strong> This refreshed draft removes obsolete address and company language from the legacy terms. It should receive legal review before production publication.</div><h2>Acceptance of terms</h2><p>By using fkplumbing.com, you agree to these Website Terms &amp; Conditions and the Privacy Policy. If you do not agree, do not use the website.</p><h2>Informational purpose</h2><p>Website content provides general information about plumbing services and common plumbing conditions. It is not a substitute for an on-site diagnosis, emergency services, utility instructions, code review, engineering advice, or legal advice. Service availability, scope, scheduling, pricing, coupons, and equipment recommendations are confirmed separately.</p><h2>Emergency conditions</h2><p>For a suspected gas leak, leave the area and contact the gas utility or emergency services from a safe location. For electrical hazards, contaminated water, fire, or an immediate threat to life or property, contact the appropriate emergency authority. Website forms are not monitored as an emergency channel.</p><h2>Use of the website</h2><p>You may use this website for lawful personal and business-information purposes. You may not misuse the site, interfere with its operation, attempt unauthorized access, introduce malicious code, scrape it in a manner that burdens the service, or reproduce protected content without permission.</p><h2>Intellectual property</h2><p>Unless otherwise stated, website text, branding, graphics, photographs, layout, and other original material are owned by or licensed to Frost &amp; Kretsch Plumbing and are protected by applicable law. Limited linking to public pages is permitted when it does not imply endorsement or misuse trademarks.</p><h2>Third-party services and links</h2><p>The website may link to mapping, review, social, financing, analytics, scheduling, or other third-party services. Those services operate under their own terms and privacy practices. A link does not guarantee or endorse third-party availability, accuracy, or security.</p><h2>Disclaimers and limitation</h2><p>The website is provided on an “as available” basis. Frost &amp; Kretsch Plumbing does not warrant that website content is error-free, complete, uninterrupted, or suitable for every property. To the extent permitted by law, the company is not liable for indirect or consequential damages arising solely from use of the website.</p><h2>Changes and governing law</h2><p>These terms may be updated by posting a revised version on this page. Michigan law governs these terms to the extent applicable, without regard to conflict-of-law rules.</p><h2>Contact</h2><p>Frost &amp; Kretsch Plumbing<br>${business.address}<br>${business.phoneDisplay}<br>${business.email}</p></div></section></main>${footer()}`;}

function blogPage(){const topics=[['Kitchen and fixture plumbing','Sink layouts, faucet and toilet problems, disposals, and practical maintenance.'],['Drains and sewer systems','Clog prevention, hydro jetting, camera inspection, sewer warning signs, and repair planning.'],['Water, pipes, and equipment','Leak detection, winterization, water heaters, sump pumps, softening, and filtration.'],['Emergency preparation','What to do before help arrives for leaks, backups, frozen piping, or a water-main problem.']];return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">One consolidated plumbing resource library</div><h1>Practical plumbing advice without duplicate city versions.</h1><p>The final blog keeps the strongest article for each topic from fkplumbing.com and macombplumbers.com, then redirects retired duplicates to the closest retained resource.</p></div></section><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Editorial structure</div><h2 class="section-title">One useful article per question.</h2></div><p class="lead">Articles are organized by plumbing topic—not copied across cities.</p></div><div class="cards">${topics.map(([title,copy])=>`<article class="card"><div class="card-body"><h3>${esc(title)}</h3><p>${esc(copy)}</p></div></article>`).join('')}</div></div></section><section class="section section-alt"><div class="wrap content-grid"><article class="article-copy"><div class="eyebrow">Consolidation rules</div><h2>Keep authority; remove repetition.</h2><ul><li>Retain the strongest and most accurate post for each distinct intent.</li><li>Preserve useful original publication history when content is retained and updated.</li><li>Merge unique value from overlapping posts before retiring weaker versions.</li><li>Redirect each retired article to the closest retained article or relevant service page—not automatically to the homepage.</li><li>Do not create per-city copies of educational posts.</li></ul><p>The final retained-post inventory will be completed during the separate cross-domain content and redirect mapping step.</p></article><aside class="sidebar"><div class="sidebar-card"><h3>Start with service</h3><a href="${pageUrl('services')}">All plumbing services →</a><a href="${pageUrl('faq')}">Frequently asked questions →</a><a href="${pageUrl('contact')}">Contact the team →</a></div></aside></div></section>${cta()}</main>${footer()}`;}

function notFoundPage(){return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">404 — page not found</div><h1>The page moved, was retired, or never existed.</h1><p>Use the final service, service-area, blog, or contact routes below instead of returning to a thin or duplicated legacy page.</p><div class="hero-actions"><a class="btn btn-primary" href="${pageUrl('services')}">Explore services</a><a class="btn btn-outline" href="${pageUrl('contact')}">Contact the team</a></div></div></section><section class="section"><div class="wrap"><div class="cards"><article class="card"><div class="card-body"><h3>Choose a plumbing service</h3><p>Emergency, drain, sewer, water heater, sump pump, leak, gas line, water treatment, fixture, and commercial help.</p><a class="text-link" href="${pageUrl('services')}">All services</a></div></article><article class="card"><div class="card-body"><h3>Confirm service coverage</h3><p>Review the controlled nine-city service-area structure and the Chesterfield headquarters.</p><a class="text-link" href="${pageUrl('service-areas')}">Service Area</a></div></article><article class="card"><div class="card-body"><h3>Call the team</h3><p>${business.phoneDisplay}<br>${business.email}</p><a class="text-link" href="${business.phoneHref}">Call now</a></div></article></div></div></section></main>${footer()}`;}

function locationServicePageV2(data){return locationServicePage(data).replace('Not interchangeable copy',`Local plumbing notes for ${esc(data.city)}`);}

function architecturePageV2(){const services=serviceInventory.filter(([slug])=>slug!=='commercial').map(([,name,,,url])=>`<li><span class="url-list">${url}</span> — ${esc(name)}</li>`).join('');const cities=Object.values(priorityCities).flat().map(city=>`<li><span class="url-list">/service-area/${city.toLowerCase().replace(/\./g,'').replace(/\s+/g,'-')}/</span> — ${esc(city)}</li>`).join('');return `${header()}<main id="main"><section class="simple-hero"><div class="wrap"><div class="eyebrow">Final lean architecture</div><h1>One final URL for each search intent.</h1><p>This sitemap is the destination authority for the later page-to-page redirect map. It does not recreate the retired service-by-city pattern.</p></div></section><section class="section"><div class="wrap"><div class="template-note"><strong>Architecture status:</strong> Static page and service URLs below are final for the content review build. Retained blog-post slugs remain subject to the separate FK/Macomb duplicate-content inventory.</div><div class="architecture-grid"><article class="architecture-card"><h2>Core and utility pages</h2><ul><li><span class="url-list">/</span> — Home</li><li><span class="url-list">/about/</span> — About</li><li><span class="url-list">/contact-us/</span> — Contact</li><li><span class="url-list">/reviews/</span> — Chesterfield HQ Reviews</li><li><span class="url-list">/service-area/</span> — Service Area hub</li><li><span class="url-list">/financing-coupons/</span> — Financing &amp; Coupons</li><li><span class="url-list">/faq/</span> — FAQ</li><li><span class="url-list">/blog/</span> — Consolidated blog archive</li><li><span class="url-list">/privacy/</span> — Privacy Policy</li><li><span class="url-list">/terms/</span> — Terms &amp; Conditions</li><li><span class="url-list">/services/</span> — Services overview</li><li><span class="url-list">/services/residential-plumbing/</span> — Residential hub</li><li><span class="url-list">/services/commercial-plumbing/</span> — Commercial hub and canonical commercial page</li></ul></article><article class="architecture-card"><h2>Core service pages</h2><ul>${services}</ul></article><article class="architecture-card"><h2>Controlled service-area pages</h2><ul>${cities}</ul></article><article class="architecture-card"><h2>Blog and system routes</h2><ul><li><span class="url-list">/blog/{retained-post-slug}/</span> — strongest retained article per topic</li><li><span class="url-list">404 template</span> — noindex system page; not included in XML sitemap</li><li><span class="url-list">/sitemap_index.xml</span> — generated XML sitemap index</li></ul><h2>Not included pending approval</h2><ul><li>Accessibility statement</li><li>Careers / application page</li></ul></article><article class="architecture-card"><h2>Consolidation rules</h2><ul><li>No service × city pages</li><li>No extra page solely to absorb a Macomb URL</li><li>Extra cities redirect to the Service Area hub or closest priority city</li><li>One consolidated blog stream with topic-level deduplication</li><li>One-hop page-to-page redirects mapped separately</li><li>One Chesterfield business entity and exact NAP</li></ul></article></div></div></section>${cta()}</main>${footer()}`;}

function finalFooter(){return `<footer class="site-footer"><div class="wrap"><div class="footer-main"><div class="footer-brand"><div class="footer-logo-panel"><img src="assets/images/official-primary-horizontal-transparent.png" alt="Frost &amp; Kretsch Plumbing"></div><p>Frost &amp; Kretsch Plumbing</p><p>${business.address}</p><a class="footer-phone" href="${business.phoneHref}">${business.phoneDisplay}</a><a href="mailto:${business.email}">${business.email}</a></div><nav class="footer-col" aria-label="Footer services"><h3>Services</h3><a href="${pageUrl('services')}">All plumbing services</a><a href="${pageUrl('emergency')}">24-Hour emergency plumbing</a><a href="${pageUrl('drain-cleaning')}">Drain cleaning &amp; hydro jetting</a><a href="${pageUrl('sewer-camera')}">Sewer &amp; camera inspection</a><a href="${pageUrl('commercial')}">Commercial plumbing</a></nav><nav class="footer-col" aria-label="Footer company links"><h3>Company</h3><a href="${pageUrl('about')}">About</a><a href="${pageUrl('reviews')}">Reviews</a><a href="${pageUrl('service-areas')}">Service Area</a><a href="${pageUrl('financing-coupons')}">Financing &amp; Coupons</a><a href="${pageUrl('faq')}">FAQ</a><a href="${pageUrl('blog')}">Blog</a><a href="${pageUrl('contact')}">Contact</a></nav></div><div class="footer-legal"><span>© 2026 Frost &amp; Kretsch Plumbing</span><span class="footer-policy-links"><a href="${pageUrl('privacy')}">Privacy</a><a href="${pageUrl('terms')}">Terms &amp; Conditions</a></span><span>Designed by Blue Nova Marketing</span><span class="version-badge">Static review mockup • not production</span></div></div></footer>`;}
