const renderers={home:homePageV2,architecture:architecturePageV2,services:servicesPage,residential:residentialPage,commercial:commercialPage,'water-heater':waterHeaterPage,emergency:()=>seoServicePage(seoServicePages.emergency),'drain-cleaning':()=>seoServicePage(seoServicePages['drain-cleaning']),'sewer-camera':()=>seoServicePage(seoServicePages['sewer-camera']),'sewer-line':()=>coreServicePage(remainingServicePages['sewer-line']),'sump-pump':()=>coreServicePage(remainingServicePages['sump-pump']),'leak-pipe':()=>coreServicePage(remainingServicePages['leak-pipe']),'gas-line':()=>coreServicePage(remainingServicePages['gas-line']),'water-treatment':()=>coreServicePage(remainingServicePages['water-treatment']),fixtures:()=>coreServicePage(remainingServicePages.fixtures),'service-areas':serviceAreasPageV2,chesterfield:chesterfieldPage,warren:()=>locationServicePageV2(locationPages.warren),'sterling-heights':()=>locationServicePageV2(locationPages['sterling-heights']),'clinton-township':()=>locationServicePageV2(locationPages['clinton-township']),'st-clair-shores':()=>locationServicePageV2(locationPages['st-clair-shores']),troy:()=>locationServicePageV2(locationPages.troy),'rochester-hills':()=>locationServicePageV2(locationPages['rochester-hills']),southfield:()=>locationServicePageV2(locationPages.southfield),'grosse-pointe':()=>locationServicePageV2(locationPages['grosse-pointe']),reviews:reviewsPage,'financing-coupons':financingCouponsPage,faq:faqPage,privacy:privacyPage,terms:termsPage,blog:blogPage,'404':notFoundPage,about:aboutPageV4,contact:contactPage};
