function initNavigation(){
  const menu=document.querySelector('.menu-btn');
  const links=document.querySelector('.nav-links');
  if(menu&&links)menu.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu';});
  const toggles=[...document.querySelectorAll('.submenu-toggle')];
  const closeSubmenus=(except=null)=>toggles.forEach(toggle=>{const item=toggle.closest('.nav-item');if(!item||item===except)return;item.classList.remove('submenu-open');toggle.setAttribute('aria-expanded','false');});
  toggles.forEach(toggle=>toggle.addEventListener('click',event=>{event.stopPropagation();const item=toggle.closest('.nav-item');const open=toggle.getAttribute('aria-expanded')==='true';closeSubmenus(item);item.classList.toggle('submenu-open',!open);toggle.setAttribute('aria-expanded',String(!open));}));
  document.addEventListener('click',()=>closeSubmenus());
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeSubmenus();});
}
function applyBusinessSchema(){
  const previous=document.getElementById('fk-plumber-schema');
  if(previous)previous.remove();
  const schema=document.createElement('script');
  schema.id='fk-plumber-schema';
  schema.type='application/ld+json';
  schema.textContent=JSON.stringify({
    '@context':'https://schema.org',
    '@type':['LocalBusiness','Plumber'],
    '@id':'https://fkplumbing.com/#plumber',
    name:'Frost & Kretsch Plumbing',
    url:'https://fkplumbing.com/',
    telephone:'(586) 675-0097',
    email:'info@fkplumbing.com',
    address:{'@type':'PostalAddress',streetAddress:'47212 Jefferson Ave',addressLocality:'Chesterfield',addressRegion:'MI',postalCode:'48047',addressCountry:'US'},
    areaServed:['Chesterfield','Warren','Sterling Heights','Clinton Township','St. Clair Shores','Troy','Rochester Hills','Southfield','Grosse Pointe'].map(name=>({'@type':'City',name:`${name}, Michigan`}))
  });
  document.head.appendChild(schema);
}
function renderPage(slug){const active=renderers[slug]?slug:'home';const [title,description]=pageMeta[active];document.title=title;const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=description;document.getElementById('app').innerHTML=renderers[active]();document.documentElement.dataset.mockup=active;applyBusinessSchema();initNavigation();}

